  perform public.configure_experience_evidence_requirements(aid,0,'[{"code":"venue_permission","label":"Venue permission","instructions":"Provide permission for the proposed activity at this venue.","requires_expiry":true}]','Review the actual venue permission and its valid dates for this activity.');
  perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and e.event_type='experience.evidence.required' and a.recipient_user_id=hid and a.workspace='worker'),'requirements reach host Activity');
  perform pg_temp.expect(pg_temp.rejects(format('select public.configure_experience_evidence_requirements(%L,0,%L,%L)',aid,'[]','A stale requirements change must fail.')),'stale requirements revision rejected');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
  evidence:=public.begin_experience_evidence_upload(aid,'venue_permission',key,'application/pdf',9,'permission.pdf');
  document_id:=(evidence->>'id')::uuid;object_name:=evidence->>'object_path';
