 perform pg_temp.expect(not exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and e.event_type='experience.application.submitted' and a.resolved_at is null),'decision resolves prior submission actions');
