 -- Canonical Experience commission: role/device authority, optimistic versions and retry.
 perform pg_temp.expect(pg_temp.rejects('select public.creator_get_experience_commission()'),'host cannot read Creator commission controls');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 declare ep integer; eg uuid; commission jsonb;
 begin
  update public.creator_elevation_grants set action_classes=array['private_evidence','policy_publish'] where creator_user_id=cid returning creator_elevation_id into eg;
  commission:=public.creator_get_experience_commission();ep:=coalesce((commission->'policy'->>'version')::integer,0);
  commission:=public.creator_publish_experience_commission(eg,ep,0,'Contract verification only; rolled back.');
  perform pg_temp.expect((commission->'policy'->>'version')::integer=ep+1 and (commission->'policy'->'value'->>'percent')::numeric=0,'published explicit zero percentage and new version confirmed');
  commission:=public.creator_publish_experience_commission(eg,ep,0,'Contract verification only; rolled back.');
  perform pg_temp.expect((commission->'policy'->>'version')::integer=ep+1,'retry does not create another policy version');
  perform pg_temp.expect(pg_temp.rejects(format('select public.creator_publish_experience_commission(%L,%s,10,%L)',eg,ep,'Stale change must be refused')),'stale update rejected');
  perform pg_temp.expect(pg_temp.rejects(format('select public.creator_publish_experience_commission(%L,%s,51,%L)',eg,ep+1,'Invalid rate must be refused')),'invalid percentage rejected');
  update public.user_sessions set is_active=false,trust_status='rejected' where user_id=cid;
  perform pg_temp.expect(pg_temp.rejects('select public.creator_get_experience_commission()'),'revoked Creator device rejected');
 end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 update public.user_sessions set is_active=false,trust_status='rejected' where user_id=hid;
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity(%L,false)',aid)),'revoked device cannot read application');
 perform pg_temp.expect(pg_temp.rejects('select public.get_my_provider_workspace_capabilities()'),'revoked device cannot obtain capabilities');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_my_experience_sessions(%L)',aid)),'revoked device cannot read sessions');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity_photos(%L)',aid)),'revoked device cannot read private photos');
end $$;
rollback;
select 'Application lifecycle, Activity delivery, retry, draft privacy and role/device rejection checks passed; all fixtures rolled back' as result;
